1	package relayproof
2	
3	import (
4		"bytes"
5		"strings"
6		"testing"
7		"unicode/utf8"
8	)
9	
10	// Character-integrity coverage: raw input bytes must be valid UTF-8, and
11	// \uXXXX escapes in any JSON string (field names and values at any depth,
12	// mapped or not) must form complete surrogate pairs. encoding/json would
13	// silently rewrite both defects to U+FFFD; these tests pin that the line
14	// fails instead, with a per-line ok:false record, a distinguishable reason,
15	// and no event — while legal non-ASCII text, paired escapes, literal U+FFFD,
16	// and escaped backslashes keep working.
17	
18	// Escape text for test inputs, written as interpreted strings so the JSON
19	// \uXXXX sequences reach the normalizer as literal backslash escapes.
20	const (
21		escGrinning    = "\\uD83D\\uDE00" // JSON escape text for 😀
22		escReplacement = "\\uFFFD"        // JSON escape text for U+FFFD
23	)
24	
25	// expectCharFailure asserts the single input line fails with no event and an
26	// error message containing every marker, and that the serialized output
27	// record is itself valid UTF-8 JSON (corrupted input bytes are never echoed
28	// back into the output).
29	func expectCharFailure(t *testing.T, input string, markers ...string) map[string]any {
30		t.Helper()
31		var out bytes.Buffer
32		failures, err := NormalizeReader(strings.NewReader(input), &out)
33		if err != nil {
34			t.Fatalf("a bad log line is not a stream error, got %v", err)
35		}
36		if failures != 1 {
37			t.Fatalf("the corrupted line must count as one failure, got %d", failures)
38		}
39		if !utf8.Valid(out.Bytes()) {
40			t.Fatalf("output must be valid UTF-8 even for corrupted input: %q", out.Bytes())
41		}
42		results := decodeResults(t, out.Bytes())
43		if len(results) != 1 {
44			t.Fatalf("expected exactly one result, got %#v", results)
45		}
46		r := results[0]
47		if r["line"] != float64(1) || r["ok"] != false {
48			t.Fatalf("corrupted line must fail as line 1: %#v", r)
49		}
50		if _, exists := r["event"]; exists {
51			t.Fatalf("corrupted line must not emit an event: %#v", r)
52		}
53		msg, _ := r["error"].(string)
54		if msg == "" {
55			t.Fatalf("corrupted line must explain itself: %#v", r)
56		}
57		if !utf8.ValidString(msg) {
58			t.Fatalf("error message must be valid UTF-8, got %q", msg)
59		}
60		for _, marker := range markers {
61			if !strings.Contains(msg, marker) {
62				t.Fatalf("error %q must contain %q", msg, marker)
63			}
64		}
65		return r
66	}
67	
68	func TestNormalizeInvalidUTF8Fails(t *testing.T) {
69		cases := []struct {
70			name  string
71			input string
72		}{
73			{"truncated sequence in mapped value", `{"timestamp":"2026-01-02T00:00:00Z","action":"log` + "\xff" + `in"}`},
74			{"invalid byte in unmapped string", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","note":"` + "\xc3\x28" + `"}`},
75			{"invalid byte in field name", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","no` + "\xe2\x80" + `te":"x"}`},
76			{"invalid byte deep in nested extra", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","extra":{"deep":["ok","` + "\xed\xa0\x80" + `"]}}`},
77			{"lone continuation byte", `{"timestamp":"2026-01-02T00:00:00Z","action":"a"}` + "\x80"},
78			{"overlong encoding", `{"timestamp":"2026-01-02T00:00:00Z","action":"` + "\xc0\xaf" + `"}`},
79		}
80		for _, tc := range cases {
81			t.Run(tc.name, func(t *testing.T) {
82				r := expectCharFailure(t, tc.input, "UTF-8")
83				msg := r["error"].(string)
84				if strings.Contains(msg, "surrogate") || strings.Contains(msg, "escape") {
85					t.Fatalf("UTF-8 corruption must not be reported as an escape problem, got %q", msg)
86				}
87			})
88		}
89	}
90	
91	func TestNormalizeUnpairedSurrogateEscapeFails(t *testing.T) {
92		cases := []struct {
93			name  string
94			input string
95		}{
96			{"lone high surrogate as action", `{"timestamp":"2026-01-02T00:00:00Z","action":"\uD800"}`},
97			{"lone high surrogate in timestamp", `{"timestamp":"2026-01-02T00:00:00\uD800Z","action":"a"}`},
98			{"lone low surrogate as action", `{"timestamp":"2026-01-02T00:00:00Z","action":"act\uDC00ion"}`},
99			{"reversed surrogate pair", `{"timestamp":"2026-01-02T00:00:00Z","action":"\uDC00\uD800"}`},
100			{"high surrogate at end of string", `{"timestamp":"2026-01-02T00:00:00Z","action":"abc\uD800"}`},
101			{"high surrogate followed by BMP escape", `{"timestamp":"2026-01-02T00:00:00Z","action":"\uD800A"}`},
102			{"high surrogate followed by another high", `{"timestamp":"2026-01-02T00:00:00Z","action":"\uD800\uD800\uDC00"}`},
103			{"high surrogate in field name", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","no\uD800te":"x"}`},
104			{"low surrogate in field name", `{"time\uDFFFstamp":"2026-01-02T00:00:00Z","action":"a"}`},
105			{"high surrogate deep in nested extra", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","extra":{"deep":["ok","y\uDBFF"]}}`},
106			{"low surrogate in input extra object", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","extra":{"k":"\uDC00"}}`},
107			{"high surrogate in nested key", `{"timestamp":"2026-01-02T00:00:00Z","action":"a","payload":{"a\uD800b":1}}`},
108			{"lowercase hex surrogate", `{"timestamp":"2026-01-02T00:00:00Z","action":"\ud800"}`},
109		}
110		for _, tc := range cases {
111			t.Run(tc.name, func(t *testing.T) {
112				r := expectCharFailure(t, tc.input, "unpaired", "surrogate")
113				msg := r["error"].(string)
114				if strings.Contains(msg, "UTF-8") {
115					t.Fatalf("unpaired escape must not be reported as UTF-8 corruption, got %q", msg)
116				}
117			})
118		}
119	}
120	
121	// Legal non-ASCII content must keep working: Chinese text, emoji, correctly
122	// paired surrogate escapes, and a literal U+FFFD the user actually wrote are
123	// all valid characters, not corruption.
124	func TestNormalizeLegalUnicodeAccepted(t *testing.T) {
125		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"登录","user":"用户😀","paired":"😀",` +
126			`"escaped_pair":"` + escGrinning + `","replacement":"�","escaped_replacement":"` + escReplacement + `"}`
127		results := runNormalize(t, input)
128		if len(results) != 1 || results[0]["ok"] != true {
129			t.Fatalf("legal unicode must succeed, got %#v", results)
130		}
131		event := eventOf(t, results[0])
132		if event["action"] != "登录" {
133			t.Fatalf("Chinese action must survive, got %v", event["action"])
134		}
135		extra := extraOf(t, results[0])
136		if extra["user"] != "用户😀" {
137			t.Fatalf("Chinese and emoji extra string must survive, got %v", extra["user"])
138		}
139		if extra["paired"] != "😀" || extra["escaped_pair"] != "😀" {
140			t.Fatalf("paired surrogate escapes must decode to the emoji, got %#v", extra)
141		}
142		if extra["replacement"] != "�" || extra["escaped_replacement"] != "�" {
143			t.Fatalf("a literal U+FFFD is valid input, not corruption, got %#v", extra)
144		}
145	}
146	
147	// A correctly paired surrogate escape in a mapped field decodes to the
148	// astral character and is a perfectly good action name.
149	func TestNormalizePairedSurrogateInMappedField(t *testing.T) {
150		results := runNormalize(t, `{"timestamp":"2026-01-02T00:00:00Z","action":"`+escGrinning+`"}`)
151		if results[0]["ok"] != true {
152			t.Fatalf("paired surrogate escape must be accepted, got %#v", results[0])
153		}
154		if got := eventOf(t, results[0])["action"]; got != "😀" {
155			t.Fatalf("paired escape must decode to the emoji, got %v", got)
156		}
157	}
158	
159	// In "\\uD800" the backslash is escaped, so uD800 is ordinary text: the line
160	// is valid and the text is preserved byte-for-byte, not treated as an
161	// escape, not flagged, and not rewritten.
162	func TestNormalizeEscapedBackslashBeforeUIsPlainText(t *testing.T) {
163		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"run","note":"\\uD800","seq":"\\` + escGrinning + `"}`
164		results := runNormalize(t, input)
165		if results[0]["ok"] != true {
166			t.Fatalf("escaped backslash text must not be flagged, got %#v", results[0])
167		}
168		extra := extraOf(t, results[0])
169		if extra["note"] != `\uD800` {
170			t.Fatalf(`escaped backslash must stay the plain text \uD800, got %v`, extra["note"])
171		}
172		// After the escaped backslash a real escape can still begin: the paired
173		// surrogate here is a genuine escape and decodes to the emoji.
174		if extra["seq"] != `\`+"😀" {
175			t.Fatalf("escape after escaped backslash must still decode, got %v", extra["seq"])
176		}
177		raw := runNormalizeRaw(t, input)
178		if !strings.Contains(raw, `\\uD800`) {
179			t.Fatalf("extra must preserve the escaped-backslash text verbatim, got %s", raw)
180		}
181	}
182	
183	// The integrity check must not disturb anything else: nested content and
184	// high-precision numbers in unmapped fields pass through byte-identical on
185	// lines that also exercise the new scanner.
186	func TestNormalizeIntegrityCheckPreservesExtraContent(t *testing.T) {
187		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a","payload":{"emoji":"` + escGrinning + `","big":9007199254740993,"list":["中文",1.0000000000000000001,"\\uD800"]}}`
188		results := runNormalizeJSON(t, input)
189		if results[0]["ok"] != true {
190			t.Fatalf("legal nested content must succeed, got %#v", results[0])
191		}
192		payload, ok := extraOf(t, results[0])["payload"].(map[string]any)
193		if !ok {
194			t.Fatalf("payload must be preserved, got %#v", extraOf(t, results[0]))
195		}
196		if payload["emoji"] != "😀" {
197			t.Fatalf("paired escape must decode, got %v", payload["emoji"])
198		}
199		mustNumber(t, payload["big"], "9007199254740993")
200		list, ok := payload["list"].([]any)
201		if !ok || len(list) != 3 {
202			t.Fatalf("nested array must be preserved, got %#v", payload["list"])
203		}
204		if list[0] != "中文" {
205			t.Fatalf("nested Chinese string must survive, got %v", list[0])
206		}
207		mustNumber(t, list[1], "1.0000000000000000001")
208		if list[2] != `\uD800` {
209			t.Fatalf("escaped-backslash text must stay verbatim, got %v", list[2])
210		}
211	}
212	
213	// Corrupted lines in a healthy stream behave like any other invalid log:
214	// one ok:false record each with the original physical line number, valid
215	// lines around them still succeed in order, the returned error is nil, and
216	// the failure count covers exactly the corrupted lines (driving exit 1).
217	func TestNormalizeCorruptedLinesInMixedStream(t *testing.T) {
218		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
219			`{"timestamp":"2026-01-02T00:00:00Z","action":"\uD800"}` + "\n" +
220			"\n" +
221			`{"timestamp":"2026-01-02T00:00:00Z","action":"bad` + "\xff" + `"}` + "\n" +
222			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n"
223		var out bytes.Buffer
224		failures, err := NormalizeReader(strings.NewReader(input), &out)
225		if err != nil {
226			t.Fatalf("per-line corruption is not a stream error, got %v", err)
227		}
228		if failures != 2 {
229			t.Fatalf("exactly the two corrupted lines must count, got %d", failures)
230		}
231		if !utf8.Valid(out.Bytes()) {
232			t.Fatalf("output must be valid UTF-8: %q", out.Bytes())
233		}
234		results := decodeResults(t, out.Bytes())
235		if len(results) != 4 {
236			t.Fatalf("expected 4 results for 5 physical lines, got %#v", results)
237		}
238		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
239			t.Fatalf("line 1 must succeed: %#v", results[0])
240		}
241		if results[1]["line"] != float64(2) || results[1]["ok"] != false {
242			t.Fatalf("line 2 (unpaired escape) must fail: %#v", results[1])
243		}
244		if !strings.Contains(results[1]["error"].(string), "surrogate") {
245			t.Fatalf("line 2 must be reported as an unpaired escape, got %q", results[1]["error"])
246		}
247		if results[2]["line"] != float64(4) || results[2]["ok"] != false {
248			t.Fatalf("line 4 (invalid UTF-8) must fail with its physical line number: %#v", results[2])
249		}
250		if !strings.Contains(results[2]["error"].(string), "UTF-8") {
251			t.Fatalf("line 4 must be reported as UTF-8 corruption, got %q", results[2]["error"])
252		}
253		if results[3]["line"] != float64(5) || results[3]["ok"] != true {
254			t.Fatalf("line 5 must still be processed: %#v", results[3])
255		}
256		if eventOf(t, results[3])["action"] != "last" {
257			t.Fatalf("input order must be preserved after corrupted lines")
258		}
259	}
