1	package relayproof
2	
3	import (
4		"fmt"
5		"strings"
6		"testing"
7		"unicode/utf16"
8	)
9	
10	// escKey renders key as a JSON member name in which every rune is spelled via
11	// a lowercase unicode escape (with UTF-16 surrogate pairs above the BMP),
12	// e.g. escKey("action") is the nine JSON bytes backslash-u-0-0-6-1... that
13	// decode back to "action". Building escaped names at runtime keeps the test
14	// source independent of how inline escape text is transported.
15	func escKey(key string) string {
16		var b strings.Builder
17		b.WriteByte('"')
18		for _, r := range key {
19			for _, u := range utf16.Encode([]rune{r}) {
20				fmt.Fprintf(&b, "\\u%04x", u)
21			}
22		}
23		b.WriteByte('"')
24		return b.String()
25	}
26	
27	// Regression coverage for the duplicate top-level field rule. Duplicates are
28	// judged by the JSON-decoded member name: a key written with a unicode escape
29	// is the same member as the literal spelling, so their coexistence fails the
30	// whole line even when both values are equal. The check runs before field
31	// validation and therefore must never degrade into a value-conflict error or
32	// let the later value win.
33	func TestNormalizeDuplicateKeysAfterJSONUnescaping(t *testing.T) {
34		withRequired := func(members string) string {
35			return `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` + members + `}`
36		}
37		cases := []struct {
38			name  string
39			input string
40			field string // decoded member name the error must identify
41			diff  bool   // the repeated members carry different values
42		}{
43			{
44				name:  "canonical name escaped then literal, equal values",
45				input: withRequired(escKey("action") + `:"a","action":"a"`),
46				field: FieldAction,
47			},
48			{
49				name:  "canonical name literal then escaped, different values",
50				input: withRequired(`"action":"a",` + escKey("action") + `:"b"`),
51				field: FieldAction,
52				diff:  true,
53			},
54			{
55				name: "escaped timestamp duplicates literal timestamp",
56				input: `{` + escKey("timestamp") + `:"2026-01-02T00:00:00Z",` +
57					`"timestamp":"2026-01-02T00:00:00Z","action":"a"}`,
58				field: FieldTimestamp,
59			},
60			{
61				name:  "alias name literal and escaped",
62				input: withRequired(`"time":"2026-01-02T00:00:00Z",` + escKey("time") + `:"2026-01-02T00:00:00Z"`),
63				field: "time",
64			},
65			{
66				name:  "unknown field escaped and literal, equal values",
67				input: withRequired(escKey("foo") + `:1,"foo":1`),
68				field: "foo",
69			},
70			{
71				name:  "unknown field literal and escaped, different values",
72				input: withRequired(`"foo":1,` + escKey("foo") + `:2`),
73				field: "foo",
74				diff:  true,
75			},
76			{
77				name:  "both members escape-encoded, equal values",
78				input: withRequired(escKey("action") + `:"a",` + escKey("action") + `:"a"`),
79				field: FieldAction,
80			},
81			{
82				name:  "Chinese member name versus its unicode escape",
83				input: withRequired(escKey("事件") + `:1,"事件":2`),
84				field: "事件",
85				diff:  true,
86			},
87		}
88		for _, tc := range cases {
89			t.Run(tc.name, func(t *testing.T) {
90				results := runNormalize(t, tc.input)
91				if len(results) != 1 || results[0]["ok"] != false {
92					t.Fatalf("decoded-same-name members must fail the whole line: %s -> %#v", tc.input, results)
93				}
94				if _, exists := results[0]["event"]; exists {
95					t.Fatalf("duplicate-field failure must not carry an event: %s -> %#v", tc.input, results[0])
96				}
97				msg, _ := results[0]["error"].(string)
98				if !strings.Contains(strings.ToLower(msg), "duplicate") {
99					t.Fatalf("error must report a duplicate field, got %q (input %s)", msg, tc.input)
100				}
101				if !strings.Contains(msg, tc.field) {
102					t.Fatalf("error must identify the decoded field name %q, got %q", tc.field, msg)
103				}
104				if tc.diff && strings.Contains(strings.ToLower(msg), "conflict") {
105					t.Fatalf("a decoded duplicate must not be reported as a value conflict: %q", msg)
106				}
107			})
108		}
109	}
110	
111	// A standard or alias field written only through escapes must normalize
112	// exactly like the literal spelling: same canonical event, same extra.
113	func TestNormalizeEscapedFieldNamesMatchLiteralSpelling(t *testing.T) {
114		literal1 := `{"timestamp":"2026-01-02T00:00:00Z","action":"a"}`
115		escaped1 := `{` + escKey("timestamp") + `:"2026-01-02T00:00:00Z",` + escKey("action") + `:"a"}`
116	
117		literal2 := `{"time":"2026-01-02T08:04:05+08:00","src_ip":"::1","event_type":" login ","user":"alice"}`
118		escaped2 := `{` + escKey("time") + `:"2026-01-02T08:04:05+08:00",` +
119			escKey("src_ip") + `:"::1",` +
120			escKey("event_type") + `:" login ",` +
121			escKey("user") + `:"alice"}`
122	
123		for i, pair := range [][2]string{{literal1, escaped1}, {literal2, escaped2}} {
124			literal := runNormalizeRaw(t, pair[0])
125			escaped := runNormalizeRaw(t, pair[1])
126			if literal != escaped {
127				t.Fatalf("escaped spelling must produce the identical result.\nliteral: %s\nescaped: %s", literal, escaped)
128			}
129			results := runNormalize(t, pair[1])
130			if results[0]["ok"] != true {
131				t.Fatalf("escaped-only field names must succeed: %#v", results[0])
132			}
133			event := eventOf(t, results[0])
134			if i == 0 {
135				if event["timestamp"] != "2026-01-02T00:00:00Z" || event["action"] != "a" {
136					t.Fatalf("escaped canonical names must map normally: %#v", event)
137				}
138				continue
139			}
140			if event["timestamp"] != "2026-01-02T00:04:05Z" || event["source_ip"] != "::1" || event["action"] != "login" {
141				t.Fatalf("escaped aliases must map to canonical fields: %#v", event)
142			}
143			if extra, _ := event["extra"].(map[string]any); extra["user"] != "alice" {
144				t.Fatalf("escaped unknown name must land in extra decoded, got %#v", event["extra"])
145			}
146		}
147	}
148	
149	// Duplicate detection is scoped to decoded top-level members only. Objects
150	// nested inside unknown fields — including objects inside array elements and
151	// inside the input's own "extra" field — keep their repeated members with
152	// their original order and values; field-like text inside string values must
153	// not trigger the rule; members differing only by case or by embedded spaces
154	// stay distinct fields.
155	func TestNormalizeDuplicateRuleScope(t *testing.T) {
156		t.Run("nested repeated members survive verbatim", func(t *testing.T) {
157			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` +
158				`"payload":{"a":1,"a":2},` +
159				`"rows":[{"b":1,"b":2},{"c":1}],` +
160				`"extra":{"inner":{"x":1,"x":2}}}`
161			results := runNormalizeJSON(t, input)
162			if results[0]["ok"] != true {
163				t.Fatalf("repeated nested members must not fail the line: %#v", results[0])
164			}
165			raw := runNormalizeRaw(t, input)
166			for _, want := range []string{
167				`"payload":{"a":1,"a":2}`,
168				`"rows":[{"b":1,"b":2},{"c":1}]`,
169				`"extra":{"inner":{"x":1,"x":2}}`,
170			} {
171				if !strings.Contains(raw, want) {
172					t.Fatalf("nested members must keep occurrence order and values\nwant %s\n got %s", want, raw)
173				}
174			}
175			extra := extraOf(t, results[0])
176			if _, ok := extra["extra"].(map[string]any); !ok {
177				t.Fatalf("the input's own extra must stay an ordinary nested unknown field: %#v", extra["extra"])
178			}
179		})
180	
181		t.Run("field-like text inside string values is inert", func(t *testing.T) {
182			// The inner text spells two "action" members, but it lives inside a
183			// JSON string value; escaping an "i" inside that value changes only
184			// the decoded string text.
185			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` +
186				`"note":"{\"action\":1, \"action\":2}","invalue":"act` + "\\u0069" + `on twice"}`
187			results := runNormalize(t, input)
188			if results[0]["ok"] != true {
189				t.Fatalf("text inside strings must not be parsed as members: %#v", results[0])
190			}
191			extra := extraOf(t, results[0])
192			if extra["note"] != `{"action":1, "action":2}` {
193				t.Fatalf("string value must be preserved verbatim: %v", extra["note"])
194			}
195			if extra["invalue"] != "action twice" {
196				t.Fatalf("the escape inside a string value must decode as value text, got %v", extra["invalue"])
197			}
198		})
199	
200		t.Run("case and space variants are distinct fields", func(t *testing.T) {
201			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` +
202				`"Foo":1,"foo":2," action":3,"foo bar":4}`
203			results := runNormalize(t, input)
204			if results[0]["ok"] != true {
205				t.Fatalf("case/space-distinct members are not duplicates: %#v", results[0])
206			}
207			extra := extraOf(t, results[0])
208			for _, key := range []string{"Foo", "foo", " action", "foo bar"} {
209				if _, ok := extra[key]; !ok {
210					t.Fatalf("distinct member %q must be kept in extra: %#v", key, extra)
211				}
212			}
213			if eventOf(t, results[0])["action"] != "a" {
214				t.Fatalf("the spaced variant must not touch the mapped action field: %#v", results[0])
215			}
216		})
217	}
218	
219	// A canonical name and its alias are different JSON members, never duplicate
220	// keys: equal values still merge, and different values are still reported as
221	// a field conflict (including when one name is escape-encoded).
222	func TestNormalizeCanonicalAndAliasAreNotDuplicateKeys(t *testing.T) {
223		consistent := []string{
224			`{"timestamp":"2026-01-02T00:00:00Z","time":"2026-01-02T00:00:00Z","action":"a"}`,
225			`{` + escKey("timestamp") + `:"2026-01-02T00:00:00Z","time":"2026-01-02T00:00:00Z","action":"a"}`,
226			`{"source_ip":"1.2.3.4","src_ip":"1.2.3.4","timestamp":"2026-01-02T00:00:00Z","action":"a"}`,
227			`{"action":"login","event_type":"login","timestamp":"2026-01-02T00:00:00Z"}`,
228		}
229		for _, in := range consistent {
230			results := runNormalize(t, in)
231			if results[0]["ok"] != true {
232				t.Fatalf("canonical+alias with equal values must merge, not duplicate-fail: %s -> %#v", in, results[0])
233			}
234		}
235	
236		conflicts := []struct {
237			input string
238			field string
239		}{
240			{`{"timestamp":"2026-01-02T00:00:00Z","time":"2026-01-02T00:05:00Z","action":"a"}`, FieldTimestamp},
241			{`{` + escKey("timestamp") + `:"2026-01-02T00:00:00Z","time":"2026-01-02T00:05:00Z","action":"a"}`, FieldTimestamp},
242			{`{"source_ip":"1.2.3.4","src_ip":"5.6.7.8","timestamp":"2026-01-02T00:00:00Z","action":"a"}`, FieldSourceIP},
243			{`{"action":"login","event_type":"logout","timestamp":"2026-01-02T00:00:00Z"}`, FieldAction},
244		}
245		for _, tc := range conflicts {
246			results := runNormalize(t, tc.input)
247			if results[0]["ok"] != false {
248				t.Fatalf("canonical+alias with different values must fail: %s", tc.input)
249			}
250			msg, _ := results[0]["error"].(string)
251			if !strings.Contains(strings.ToLower(msg), "conflict") {
252				t.Fatalf("different values must be a value conflict, got %q (%s)", msg, tc.input)
253			}
254			if strings.Contains(strings.ToLower(msg), "duplicate") {
255				t.Fatalf("canonical+alias must never be called duplicate keys: %q", msg)
256			}
257			if !strings.Contains(msg, tc.field) {
258				t.Fatalf("conflict error must name %q, got %q", tc.field, msg)
259			}
260		}
261	}
262	
263	// In a mixed stream, one duplicate-key line fails alone: the surrounding
264	// legal lines still come out in input order, blank lines only advance the
265	// physical line counter, the failure keeps its line number with no event, and
266	// exactly that one line is counted.
267	func TestNormalizeDuplicateKeyMixedStream(t *testing.T) {
268		dupLine := `{"timestamp":"2026-01-02T00:00:00Z","action":"a",` + escKey("action") + `:"b"}`
269		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
270			"\n" +
271			dupLine + "\n" +
272			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n"
273		results := runNormalize(t, input)
274		if len(results) != 3 {
275			t.Fatalf("expected 3 results for 4 physical lines, got %#v", results)
276		}
277		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
278			t.Fatalf("leading valid log must succeed on line 1: %#v", results[0])
279		}
280		if eventOf(t, results[0])["action"] != "first" {
281			t.Fatalf("line 1 content must survive in order: %#v", results[0])
282		}
283		bad := results[1]
284		if bad["line"] != float64(3) || bad["ok"] != false {
285			t.Fatalf("duplicate log must fail on physical line 3: %#v", bad)
286		}
287		if _, exists := bad["event"]; exists {
288			t.Fatalf("failed line must not carry an event: %#v", bad)
289		}
290		msg, _ := bad["error"].(string)
291		if !strings.Contains(strings.ToLower(msg), "duplicate") || !strings.Contains(msg, FieldAction) {
292			t.Fatalf("error must identify the duplicate %q, got %q", FieldAction, msg)
293		}
294		if strings.Contains(strings.ToLower(msg), "conflict") {
295			t.Fatalf("different values must still be a duplicate error, got %q", msg)
296		}
297		if results[2]["line"] != float64(4) || results[2]["ok"] != true {
298			t.Fatalf("trailing valid log must still succeed on line 4: %#v", results[2])
299		}
300		if eventOf(t, results[2])["action"] != "last" {
301			t.Fatalf("line 4 content must survive in order: %#v", results[2])
302		}
303	}
