25	// escKey renders key as a JSON member name spelled entirely with unicode
26	// escapes (with UTF-16 surrogate pairs above the BMP), so tests can feed a
27	// \uXXXX-encoded key without embedding escape text in the source.
28	func escKey(key string) string {
29		var b strings.Builder
30		b.WriteByte('"')
31		for _, r := range key {
32			for _, u := range utf16.Encode([]rune{r}) {
33				fmt.Fprintf(&b, "\\u%04x", u)
34			}
35		}
36		b.WriteByte('"')
37		return b.String()
38	}
39	
40	// normalizeBin is the compiled relayproof binary shared by all tests in
41	// this package, built once from the current sources.
42	var normalizeBin string
43	
44	func TestMain(m *testing.M) {
45		dir, err := os.MkdirTemp("", "relayproof-cli-test")
46		if err != nil {
47			panic(err)
48		}
49		defer os.RemoveAll(dir)
50	
51		normalizeBin = filepath.Join(dir, "relayproof")
52		build := exec.Command("go", "build", "-o", normalizeBin, ".")
53		if out, err := build.CombinedOutput(); err != nil {
54			panic("building relayproof for CLI tests: " + err.Error() + "\n" + string(out))
55		}
56		os.Exit(m.Run())
57	}
58	
59	// cliResult captures everything the surrounding shell can observe from one
60	// normalize invocation.
61	type cliResult struct {
62		stdout   string
63		stderr   string
64		exitCode int
65	}
66	
67	// runNormalizeCLI executes `relayproof normalize` with stdin fed from r and
68	// records stdout, stderr, and the exit code. A process that cannot be
69	// started at all fails the test rather than masquerading as an exit status.
70	func runNormalizeCLI(t *testing.T, stdin io.Reader) cliResult {
71		t.Helper()
72		cmd := exec.Command(normalizeBin, "normalize")
73		cmd.Stdin = stdin
74		var stdout, stderr bytes.Buffer
75		cmd.Stdout = &stdout
76		cmd.Stderr = &stderr
77	
78		err := cmd.Run()
79		result := cliResult{stdout: stdout.String(), stderr: stderr.String()}
80		switch {
81		case err == nil:
82			result.exitCode = 0
83		default:
84			exitErr, ok := err.(*exec.ExitError)
85			if !ok {
86				t.Fatalf("normalize process could not run: %v", err)
87			}
88			result.exitCode = exitErr.ExitCode()
89		}
90		return result
91	}
92	
93	// decodeStdoutResults parses stdout as newline-delimited JSON result
94	// objects. Any line that is not a JSON object — help text, a plain-text
95	// notice, a log fragment — fails the test, because stdout must carry
96	// machine-readable results and nothing else.
97	func decodeStdoutResults(t *testing.T, stdout string) []map[string]any {
98		t.Helper()
99		var results []map[string]any
100		decoder := json.NewDecoder(strings.NewReader(stdout))
101		for {
102			var record map[string]any
103			if err := decoder.Decode(&record); err != nil {
104				if err == io.EOF {
105					return results
106				}
107				t.Fatalf("stdout must contain only JSON result objects, got decode error %v after %d records: %q",
108					err, len(results), stdout)
109			}
110			results = append(results, record)
111		}
112	}
113	
114	// eventOf extracts the event object of a successful result.
115	func eventOf(t *testing.T, result map[string]any) map[string]any {
116		t.Helper()
117		event, ok := result["event"].(map[string]any)
118		if !ok {
119			t.Fatalf("result has no event object: %#v", result)
120		}
121		return event
122	}
123	
124	// A healthy run: every log line normalizes, stdout carries one JSON result
125	// per line and nothing else, stderr stays silent, and the process exits 0.
126	// Alias keys must surface under their canonical names, the timestamp must be
127	// converted to UTC, the action trimmed, and unmapped fields must survive in
128	// extra with their JSON types intact.
129	func TestNormalizeCLIAllValidExitsZero(t *testing.T) {
130		input := `{"time":"2026-01-02T08:04:05+08:00","src_ip":"2001:db8::1","event_type":"  login  ","user":" alice ","retries":2,"ok":true}` + "\n" +
131			`{"timestamp":"2026-01-02T00:00:00Z","action":"logout","source_ip":"10.0.0.9","tags":["a","b"],"meta":{"trace":"t-1"}}` + "\n"
132	
133		result := runNormalizeCLI(t, strings.NewReader(input))
134	
135		if result.exitCode != 0 {
136			t.Fatalf("all-valid input must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
137		}
138		if result.stderr != "" {
139			t.Fatalf("a clean run must not write to stderr, got %q", result.stderr)
140		}
141	
142		results := decodeStdoutResults(t, result.stdout)
143		if len(results) != 2 {
144			t.Fatalf("expected one result per input line, got %#v", results)
145		}
146	
147		first := results[0]
148		if first["line"] != float64(1) || first["ok"] != true {
149			t.Fatalf("first result must report line 1 as ok: %#v", first)
150		}
151		event := eventOf(t, first)
152		if event["timestamp"] != "2026-01-02T00:04:05Z" {
153			t.Fatalf("alias time must land in timestamp converted to UTC, got %v", event["timestamp"])
154		}
155		if event["source_ip"] != "2001:db8::1" {
156			t.Fatalf("alias src_ip must land in source_ip, got %v", event["source_ip"])
157		}
158		if event["action"] != "login" {
159			t.Fatalf("alias event_type must land in action with whitespace trimmed, got %v", event["action"])
160		}
161		extra, ok := event["extra"].(map[string]any)
162		if !ok {
163			t.Fatalf("unmapped fields must be kept in extra: %#v", event)
164		}
165		if extra["user"] != " alice " {
166			t.Fatalf("extra strings must pass through verbatim, got %v", extra["user"])
167		}
168		if extra["retries"] != float64(2) {
169			t.Fatalf("extra numbers must stay numbers, got %#v", extra["retries"])
170		}
171		if extra["ok"] != true {
172			t.Fatalf("extra booleans must stay booleans, got %#v", extra["ok"])
173		}
174	
175		second := results[1]
176		if second["line"] != float64(2) || second["ok"] != true {
177			t.Fatalf("second result must report line 2 as ok: %#v", second)
178		}
179		event = eventOf(t, second)
180		if event["action"] != "logout" || event["source_ip"] != "10.0.0.9" {
181			t.Fatalf("canonical fields must round-trip unchanged: %#v", event)
182		}
183		extra, ok = event["extra"].(map[string]any)
184		if !ok {
185			t.Fatalf("structured extra fields must be kept: %#v", event)
186		}
187		tags, ok := extra["tags"].([]any)
188		if !ok || len(tags) != 2 || tags[0] != "a" || tags[1] != "b" {
189			t.Fatalf("extra arrays must keep their element order and types, got %#v", extra["tags"])
190		}
191		meta, ok := extra["meta"].(map[string]any)
192		if !ok || meta["trace"] != "t-1" {
193			t.Fatalf("extra objects must survive the command entry intact, got %#v", extra["meta"])
194		}
195	}
196	
197	// The key mixed-input case: a field-invalid log between two valid ones. The
198	// bad line gets an ok:false result with an explanatory error and no event,
199	// the surrounding valid lines still succeed in input order, and the process
200	// exits 1 — it must neither stop at the first bad line nor let the trailing
201	// success reset the status to 0. stderr stays empty because the failure is
202	// described by its own result record.
203	func TestNormalizeCLIInvalidLineBetweenValidOnesExitsOne(t *testing.T) {
204		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
205			`{"timestamp":"not-a-time","action":"broken"}` + "\n" +
206			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n"
207	
208		result := runNormalizeCLI(t, strings.NewReader(input))
209	
210		if result.exitCode != 1 {
211			t.Fatalf("one invalid log must set exit status 1, got %d (stderr: %q)", result.exitCode, result.stderr)
212		}
213		if result.stderr != "" {
214			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
215		}
216	
217		results := decodeStdoutResults(t, result.stdout)
218		if len(results) != 3 {
219			t.Fatalf("processing must continue past the bad line; expected 3 results, got %#v", results)
220		}
221	
222		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
223			t.Fatalf("the leading valid log must succeed on line 1: %#v", results[0])
224		}
225		if eventOf(t, results[0])["action"] != "first" {
226			t.Fatalf("line 1 event content mismatch: %#v", results[0])
227		}
228	
229		bad := results[1]
230		if bad["line"] != float64(2) || bad["ok"] != false {
231			t.Fatalf("the invalid log must be reported as line 2 with ok=false: %#v", bad)
232		}
233		if _, exists := bad["event"]; exists {
234			t.Fatalf("a failed line must not carry an event: %#v", bad)
235		}
236		message, ok := bad["error"].(string)
237		if !ok || message == "" {
238			t.Fatalf("a failed line must explain itself in error: %#v", bad)
239		}
240		if !strings.Contains(message, "timestamp") {
241			t.Fatalf("the error must name the offending field, got %q", message)
242		}
243	
244		if results[2]["line"] != float64(3) || results[2]["ok"] != true {
245			t.Fatalf("the trailing valid log must still succeed on line 3: %#v", results[2])
246		}
247		if eventOf(t, results[2])["action"] != "last" {
248			t.Fatalf("line 3 event content mismatch: %#v", results[2])
249		}
250	}
