252	// Blank lines produce no results but still consume physical line numbers,
253	// and a final complete log without a trailing newline is processed like any
254	// other. The run is clean, so the exit status is 0 and stderr stays empty.
255	func TestNormalizeCLIBlankLinesAndMissingFinalNewline(t *testing.T) {
256		input := "\n" +
257			"   \n" +
258			`{"timestamp":"2026-01-02T00:00:00Z","action":"alpha"}` + "\n" +
259			"\t\n" +
260			`{"timestamp":"2026-01-02T00:00:01Z","action":"omega"}` // no trailing newline
261	
262		result := runNormalizeCLI(t, strings.NewReader(input))
263	
264		if result.exitCode != 0 {
265			t.Fatalf("blank lines and a newline-less tail must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
266		}
267		if result.stderr != "" {
268			t.Fatalf("a clean run must not write to stderr, got %q", result.stderr)
269		}
270	
271		results := decodeStdoutResults(t, result.stdout)
272		if len(results) != 2 {
273			t.Fatalf("blank lines must not produce results, got %#v", results)
274		}
275		if results[0]["line"] != float64(3) {
276			t.Fatalf("line numbers must count blank physical lines, got %#v", results[0])
277		}
278		if results[0]["ok"] != true || eventOf(t, results[0])["action"] != "alpha" {
279			t.Fatalf("line 3 result mismatch: %#v", results[0])
280		}
281		if results[1]["line"] != float64(5) {
282			t.Fatalf("the final log must keep its physical line number 5, got %#v", results[1])
283		}
284		if results[1]["ok"] != true || eventOf(t, results[1])["action"] != "omega" {
285			t.Fatalf("a final line without newline must normalize normally: %#v", results[1])
286		}
287	}
288	
289	// Empty input — and input holding only blank lines — ends quietly: no
290	// results, no diagnostics, exit status 0.
291	func TestNormalizeCLIEmptyOrBlankOnlyInput(t *testing.T) {
292		cases := []struct {
293			name  string
294			input string
295		}{
296			{"completely empty", ""},
297			{"only blank lines", "\n   \n\t\n"},
298		}
299		for _, tc := range cases {
300			t.Run(tc.name, func(t *testing.T) {
301				result := runNormalizeCLI(t, strings.NewReader(tc.input))
302				if result.exitCode != 0 {
303					t.Fatalf("input without logs must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
304				}
305				if result.stdout != "" {
306					t.Fatalf("no logs means no results on stdout, got %q", result.stdout)
307				}
308				if result.stderr != "" {
309					t.Fatalf("no logs means no diagnostics on stderr, got %q", result.stderr)
310				}
311			})
312		}
313	}
314	
315	// A stdin read failure before any complete log line is a stream-level
316	// problem, not a bad log: the process exits 2, stderr explains the read
317	// failure with the normalize: prefix, and stdout carries no per-line
318	// results — the failure must not be disguised as one log's field error.
319	func TestNormalizeCLIReadErrorExitsTwo(t *testing.T) {
320		// Reading a directory fails deterministically on the first Read, before
321		// any byte of a log line can arrive.
322		dir, err := os.Open(".")
323		if err != nil {
324			t.Fatalf("opening a directory as failing stdin: %v", err)
325		}
326		defer dir.Close()
327	
328		result := runNormalizeCLI(t, dir)
329	
330		if result.exitCode != 2 {
331			t.Fatalf("a stdin read failure must exit 2, got %d (stderr: %q)", result.exitCode, result.stderr)
332		}
333		if result.stdout != "" {
334			t.Fatalf("no complete log line means no results on stdout, got %q", result.stdout)
335		}
336		if !strings.HasPrefix(result.stderr, "normalize: ") {
337			t.Fatalf("the read failure must be reported with the normalize: prefix, got %q", result.stderr)
338		}
339		if !strings.Contains(strings.ToLower(result.stderr), "read") {
340			t.Fatalf("the diagnostic must identify a read failure, got %q", result.stderr)
341		}
342	}
343	
344	// A log line with corrupted characters — invalid UTF-8 bytes or an unpaired
345	// \uXXXX surrogate escape anywhere in the object, including deep inside
346	// unmapped fields — is an ordinary per-line failure: one ok:false record with
347	// the physical line number and a reason that distinguishes the two defects,
348	// no event, valid lines around it still processed in order, exit status 1,
349	// and stderr empty. The failure records themselves must be valid UTF-8 JSON:
350	// corrupted input bytes are never echoed back into the output.
351	func TestNormalizeCLICorruptedCharactersExitOne(t *testing.T) {
352		input := []byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
353			`{"timestamp":"2026-01-02T00:00:00Z","action":"bad` + "\xff\xfe" + `"}` + "\n" +
354			`{"timestamp":"2026-01-02T00:00:00Z","action":"ok","extra":{"deep":["` + "\\uD800" + `"]}}` + "\n" +
355			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n")
356	
357		result := runNormalizeCLI(t, bytes.NewReader(input))
358	
359		if result.exitCode != 1 {
360			t.Fatalf("corrupted log lines must set exit status 1, got %d (stderr: %q)", result.exitCode, result.stderr)
361		}
362		if result.stderr != "" {
363			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
364		}
365		if !utf8.ValidString(result.stdout) {
366			t.Fatalf("stdout must be valid UTF-8 even for corrupted input, got %q", result.stdout)
367		}
368	
369		results := decodeStdoutResults(t, result.stdout)
370		if len(results) != 4 {
371			t.Fatalf("processing must continue past corrupted lines; expected 4 results, got %#v", results)
372		}
373		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
374			t.Fatalf("the leading valid log must succeed on line 1: %#v", results[0])
375		}
376	
377		badUTF8 := results[1]
378		if badUTF8["line"] != float64(2) || badUTF8["ok"] != false {
379			t.Fatalf("the invalid-UTF-8 log must fail as line 2: %#v", badUTF8)
380		}
381		if _, exists := badUTF8["event"]; exists {
382			t.Fatalf("a corrupted line must not carry an event: %#v", badUTF8)
383		}
384		msg, _ := badUTF8["error"].(string)
385		if !strings.Contains(msg, "UTF-8") {
386			t.Fatalf("invalid bytes must be reported as UTF-8 corruption, got %q", msg)
387		}
388	
389		badEscape := results[2]
390		if badEscape["line"] != float64(3) || badEscape["ok"] != false {
391			t.Fatalf("the unpaired-escape log must fail as line 3: %#v", badEscape)
392		}
393		if _, exists := badEscape["event"]; exists {
394			t.Fatalf("a corrupted line must not carry an event: %#v", badEscape)
395		}
396		msg, _ = badEscape["error"].(string)
397		if !strings.Contains(msg, "surrogate") {
398			t.Fatalf("an unpaired escape deep in extra must be reported as a surrogate problem, got %q", msg)
399		}
400	
401		if results[3]["line"] != float64(4) || results[3]["ok"] != true {
402			t.Fatalf("the trailing valid log must still succeed on line 4: %#v", results[3])
403		}
404		if eventOf(t, results[3])["action"] != "last" {
405			t.Fatalf("line 4 event content mismatch: %#v", results[3])
406		}
407	}
408	
409	// A duplicate top-level key written with a unicode escape is the same failure
410	// as a literal repeated key. With one such line between legal logs (and a
411	// blank line shifting physical numbers), the CLI must emit per-line JSON
412	// results in order, keep the failure's line number with no event and a reason
413	// that names the field, and still exit 1: trailing valid lines never reset
414	// the status. An escape-only spelling of a standard field is a normal event.
415	func TestNormalizeCLIEscapedDuplicateKeyExitsOne(t *testing.T) {
416		dup := `{"timestamp":"2026-01-02T00:00:00Z","action":"first",` + escKey("action") + `:"second"}`
417		escapedOnly := `{` + escKey("timestamp") + `:"2026-01-02T08:04:05+08:00",` + escKey("action") + `:"ok"}`
418		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
419			dup + "\n" +
420			"  \n" +
421			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n" +
422			escapedOnly
423	
424		result := runNormalizeCLI(t, strings.NewReader(input))
425	
426		if result.exitCode != 1 {
427			t.Fatalf("a duplicate-key line must set exit status 1 even with later valid logs, got %d (stderr: %q)",
428				result.exitCode, result.stderr)
429		}
430		if result.stderr != "" {
431			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
432		}
433	
434		results := decodeStdoutResults(t, result.stdout)
435		if len(results) != 4 {
436			t.Fatalf("blank lines produce no output; expected 4 results, got %#v", results)
437		}
438		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
439			t.Fatalf("leading valid log must succeed on line 1: %#v", results[0])
440		}
441		if eventOf(t, results[0])["action"] != "first" {
442			t.Fatalf("line 1 event content mismatch: %#v", results[0])
443		}
444	
445		bad := results[1]
446		if bad["line"] != float64(2) || bad["ok"] != false {
447			t.Fatalf("the escaped duplicate key must fail as line 2: %#v", bad)
448		}
449		if _, exists := bad["event"]; exists {
450			t.Fatalf("a failed line must not carry an event: %#v", bad)
451		}
452		message, ok := bad["error"].(string)
453		if !ok || message == "" {
454			t.Fatalf("the failed line must explain itself: %#v", bad)
455		}
456		if !strings.Contains(strings.ToLower(message), "duplicate") || !strings.Contains(message, "action") {
457			t.Fatalf("error must identify the duplicate action field, got %q", message)
458		}
459		if strings.Contains(strings.ToLower(message), "conflict") {
460			t.Fatalf("a decoded duplicate key must not be reported as an action conflict: %q", message)
461		}
462	
463		if results[2]["line"] != float64(4) || results[2]["ok"] != true {
